from __future__ import annotations

"""Base dashboard seeder used by ``seed_full_dashboard_demo_data.py``.

The source is embedded in a compressed payload to keep this compatibility module
self-contained. Importing this file exposes ``seed_full_dashboard_data`` and all
supporting helpers expected by the multi-school demo seeder.
"""

import base64
import gzip

_PAYLOAD = ""

exec(compile(gzip.decompress(base64.b64decode(_PAYLOAD)), __file__, "exec"), globals(), globals())
